// Astrology: the astrologer's page as the 16th and 17th centuries made it — research/14-astrology.md. The figure of
// heaven in the English square form (Lilly, Christian Astrology, 1647; the casebook of Norris Purslow, 1690s): a square,
// a diamond through the middles of its sides, a square in the middle for the day, the year and the hour, the corners
// ruled in to it; twelve triangles, the houses, each cusp's sign written along the line it begins on, its degree after
// it. The volvelle (Apian, Astronomicum Caesareum, 1540; the paper volvelle of Clavis astrologiae elimata): compass
// circles, a ring of the signs, a degree ring checkered black and white, the aspects drawn as lines from one place with
// their signs threaded on them. The ephemeris (Lilly's tables; Regiomontanus): ruled columns, the planets at the head over
// the signs they stand in, a double rule beneath. Two inks: a brown-black for the ruling and the figures, a red (red
// lead, vermilion) for the signs and the capitals, as the rubricated calendars and Knodius's wheel (1589) have it.
//   marks: compass and ruler (pen: even, a round nib), and the signs written freehand (sketch), by the ink engine's writer.
//   letters: lettering (IM FELL Double Pica, the Oxford types of the 1670s, OFL) and the signs printed as the period cut
//     them, traced (tools/upright.py, tools/traceshape.py) from the Clavis volvelle (the zodiac) and Lilly's ephemeris
//     head (the planets), as coverage laid or written by the ink engine (kit/inkletter.js).
// The style object has occult.js's signatures (tests/astrology.html lays it as tests/occult.html lays occult):
//   paraph(x, base, u, seed, rich, k?)   the chapter's sign (k: 0..11, Aries first)
//   filler(x0, x1, yTop, yBase, kind, seed, rich, k?)   kind: 'aspects' | 'signs' | 'degrees' | 'rule' (a heading's)
//   breakMark(cx, y, measure, rank, seed, rich, u, n?)   rank 1: a small volvelle on its rules; rank 2: the volvelle of aspects
//   initial(o) -> { marks, letters, width }   (o: ch, G: { box }, big, rich, seed, set: 'square' | 'volvelle', u, n)
//   frames.{ quote, figure, code, pull, aside, nav }(args), palette.{ light, dark }
import { noise2 } from '../marks.js';

const fnv = s => { let h = 2166136261; for (const c of String(s)) h = Math.imul(h ^ c.codePointAt(0), 16777619); return h >>> 0; };
const mulberry = a => () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
const rng = (seed, name) => mulberry(fnv(name + ':' + seed));
const TAU = 2 * Math.PI;
const add = (a, b, k = 1) => [a[0] + b[0] * k, a[1] + b[1] * k];
const lerp = (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
const unit = v => { const l = Math.hypot(v[0], v[1]) || 1; return [v[0] / l, v[1] / l]; };
const arclen = p => p.reduce((a, q, i) => i ? a + Math.hypot(q[0] - p[i - 1][0], q[1] - p[i - 1][1]) : 0, 0);
function resample(p, ds = .6) {
  const out = [p[0]]; let carry = 0;
  for (let i = 1; i < p.length; i++) { const [x0, y0] = p[i - 1], [x1, y1] = p[i], l = Math.hypot(x1 - x0, y1 - y0); let t = ds - carry;
    while (t <= l) { out.push([x0 + (x1 - x0) * t / l, y0 + (y1 - y0) * t / l]); t += ds; } carry = l - (t - ds); }
  if (Math.hypot(out.at(-1)[0] - p.at(-1)[0], out.at(-1)[1] - p.at(-1)[1]) > 1e-3) out.push(p.at(-1)); return out;
}
const arc = (c, r, a0, a1, n = 0) => { n ||= Math.max(10, Math.ceil(Math.abs(a1 - a0) * r / 1.2)); return Array.from({ length: n + 1 }, (_, k) => { const a = a0 + (a1 - a0) * k / n; return [c[0] + r * Math.cos(a), c[1] + r * Math.sin(a)]; }); };
const polar = (c, r, a) => [c[0] + r * Math.cos(a), c[1] + r * Math.sin(a)];

// ---- the ruler, the compass and the pen ------------------------------------------------------------------------------
// The ruling of a figure in the sources is ~0.3–0.5 % of its side (Purslow's pen, Lilly's rule); on a screen never under
// 1.3 px. A compass's circle is struck in one sweep and even; the signs and the cusps' writing are the hand's.
export const LW = u => Math.max(1.3, Math.min(2.1, u * .15));
function pen(pts, W, { col = 'k', seed = 0, wob = .04 } = {}) {
  W = Math.max(1.2, W); const P = resample(pts, .6), L = arclen(P), n = noise2(seed * 7 + 11 | 0), o = (seed * .37) % 50;
  return { pts: P, w: W, hair: W * .92, col, press: f => 1 + wob * 2 * (n(f * L / 14 + o, o) - .5), rho: 0 };
}
// a pen in a sure hand: bent a little off true, swelling where it turns and as it sets down, lifting off at the end; one
// continuous stroke, however many turns (the medium merges the ink where it runs over itself)
function sketch(pts, W, { col = 'k', seed = 0, amp = 0, swell = .22, enter = .8, leave = .7, press = null } = {}) {
  W = Math.max(1.2, W); const P0 = resample(pts, .5), n = P0.length, L = arclen(P0), nz = noise2(seed * 13 + 5 | 0), nz2 = noise2(seed * 29 + 3 | 0), lam = Math.max(18, L * .33);
  let s = 0; const P = P0.map((p, i) => { if (i) s += Math.hypot(p[0] - P0[i - 1][0], p[1] - P0[i - 1][1]);
    const a = P0[Math.max(0, i - 1)], b = P0[Math.min(n - 1, i + 1)], t = unit([b[0] - a[0], b[1] - a[1]]), d = amp * 2 * (nz(s / lam + seed % 37, 3.7) - .5) * Math.min(1, s / 6, (L - s) / 6);
    return [p[0] - t[1] * d, p[1] + t[0] * d]; });
  const k = new Float32Array(n); s = 0;
  for (let i = 0; i < n; i++) { if (i) s += Math.hypot(P[i][0] - P[i - 1][0], P[i][1] - P[i - 1][1]); const j0 = Math.max(0, i - 5), j1 = Math.min(n - 1, i + 5);
    const u = unit([P[i][0] - P[j0][0], P[i][1] - P[j0][1]]), v = unit([P[j1][0] - P[i][0], P[j1][1] - P[i][1]]), turn = i > 0 && i < n - 1 ? 1 - (u[0] * v[0] + u[1] * v[1]) : 0;
    k[i] = (1 + swell * Math.min(1, turn * 3) + .1 * 2 * (nz2(s / 22, 1.3) - .5)) * (enter + (1 - enter) * Math.min(1, s / Math.max(4, W * 3))) * (leave + (1 - leave) * Math.min(1, (L - s) / Math.max(5, W * 4))) * (press ? press(L ? s / L : 0) : 1); }
  return { pts: P, w: W, hair: W * .92, col, press: f => k[Math.min(n - 1, Math.round(f * (n - 1)))], rho: .6 };
}
// a circle struck with the compass, one sweep from the top round and a little past it
const circle = (c, r, W, o = {}) => pen(arc(c, r, -Math.PI / 2 - .05, -Math.PI / 2 + TAU + .06), W, o);
// a rule pulled with the ruler: a shade of bow, a little past its ends, heavier where the pen sets down
const rule = (a, b, W, o = {}) => { const L = Math.hypot(b[0] - a[0], b[1] - a[1]), t = unit([b[0] - a[0], b[1] - a[1]]), nr = [-t[1], t[0]], bow = .003 * L * (rng(o.seed ?? 0, 'bow')() - .5) * 2, run = o.run ?? 0;
  const A = add(a, t, -run), B = add(b, t, run), M = Math.hypot(B[0] - A[0], B[1] - A[1]);
  return sketch(Array.from({ length: 9 }, (_, i) => add(add(A, t, i / 8 * M), nr, bow * 4 * i / 8 * (1 - i / 8))), W, { amp: Math.min(.4, L * .0015), swell: 0, enter: .88, leave: .85, ...o }); };
// a straight rule a -> b less the parts inside the holes ({ c, r } circles, { box } boxes): the pieces left
function clip(a, b, holes) {
  const L = Math.hypot(b[0] - a[0], b[1] - a[1]), at = t => lerp(a, b, t), cut = [];
  for (const h of holes) {
    if (h.c) { const dx = b[0] - a[0], dy = b[1] - a[1], fx = a[0] - h.c[0], fy = a[1] - h.c[1], A = dx * dx + dy * dy, Bq = 2 * (fx * dx + fy * dy), C = fx * fx + fy * fy - h.r * h.r, D = Bq * Bq - 4 * A * C;
      if (D > 0) { const s = Math.sqrt(D); cut.push([(-Bq - s) / (2 * A), (-Bq + s) / (2 * A)]); } }
    else { const [X0, Y0, X1, Y1] = h.box; let t0 = 0, t1 = 1, ok = true;
      for (const [p, q] of [[-(b[0] - a[0]), a[0] - X0], [b[0] - a[0], X1 - a[0]], [-(b[1] - a[1]), a[1] - Y0], [b[1] - a[1], Y1 - a[1]]]) {
        if (!p) { if (q < 0) ok = false; continue; } const r = q / p; if (p < 0) t0 = Math.max(t0, r); else t1 = Math.min(t1, r); }
      if (ok && t0 < t1) cut.push([t0, t1]); } }
  cut.sort((x, y) => x[0] - y[0]); const out = []; let t = 0;
  for (const [c0, c1] of cut) { if (c0 > t) out.push([t, Math.min(1, c0)]); t = Math.max(t, c1); }
  if (t < 1) out.push([t, 1]);
  return out.filter(([p, q]) => (q - p) * L > 2.5).map(([p, q]) => [at(p), at(q)]);
}

